 CREATE TABLE CITTADINANZA 
   (	
    CODICE NUMERIC(4,0), 
    CITTADINANZA VARCHAR(128), 
    CF VARCHAR(5), 
    DISABILITATO NUMERIC(1,0),  
    FLG_PAESE_COMUNITARIO NUMERIC(1,0)
   ) ENGINE=INNODB DEFAULT CHARSET=utf8;
 
ALTER TABLE CITTADINANZA ADD CONSTRAINT PK_CITTADINANZA PRIMARY KEY (CODICE);

